/* ===================== syntax highlighting ===================== */
const PY_KW = new Set("False None True and as assert break class continue def del elif else except finally for from global if import in is lambda nonlocal not or pass raise return try while with yield".split(" "));
const PY_BI = new Set("print input len range int float str list tuple dict set type open sum max min sorted round abs enumerate zip next bool".split(" "));
const SQL_KW = new Set("SELECT FROM WHERE AND OR NOT INSERT INTO VALUES UPDATE SET DELETE CREATE TABLE DATABASE USE SHOW DROP ALTER ADD PRIMARY KEY NULL IS IN BETWEEN LIKE ORDER BY ASC DESC GROUP HAVING DISTINCT AS JOIN NATURAL DESCRIBE TABLES DATABASES INT FLOAT CHAR VARCHAR DATE UNIQUE".split(" "));
const SQL_FN = new Set("COUNT SUM AVG MAX MIN ROUND MOD POWER UPPER LOWER UCASE LCASE MID SUBSTR SUBSTRING LENGTH LEFT RIGHT INSTR LTRIM RTRIM TRIM NOW MONTH MONTHNAME YEAR DAY DAYNAME".split(" "));
function detectLang(code){
  if(/^\s*(def |import |from \w+ import|for .+:|while .+:|if .+:|print\(|try:|with open|[A-Za-z_][\w.\[\]']*\s*(=|\+=|-=|\*=)[^=])/m.test(code)) return "python";
  if(/^\s*(SELECT|CREATE|INSERT|UPDATE|DELETE|ALTER|DROP|SHOW|USE|DESCRIBE)\b/m.test(code)) return "sql";
  return "text";
}
function highlight(code, lang){
  if(lang==="text") return esc(code);
  const re = lang==="python"
    ? /(#[^\n]*)|('''[\s\S]*?'''|"""[\s\S]*?"""|'(?:\\.|[^'\\\n])*'|"(?:\\.|[^"\\\n])*")|(\b\d+(?:\.\d+)?\b)|([A-Za-z_]\w*)|([=+\-*/%<>!]+)|([\s\S])/g
    : /(--[^\n]*)|('(?:''|[^'\n])*')|(\b\d+(?:\.\d+)?\b)|([A-Za-z_]\w*)|([=+\-*/%<>!]+)|([\s\S])/g;
  let out="", m;
  while((m=re.exec(code))){
    const [t,c,s,n,w,o] = m;
    if(c) out+=`<span class="tk-c">${esc(c)}</span>`;
    else if(s) out+=`<span class="tk-s">${esc(s)}</span>`;
    else if(n) out+=`<span class="tk-n">${n}</span>`;
    else if(w){
      if(lang==="python"){
        if(PY_KW.has(w)) out+=`<span class="tk-k">${w}</span>`;
        else if(PY_BI.has(w)) out+=`<span class="tk-b">${w}</span>`;
        else if(code[re.lastIndex]==="(") out+=`<span class="tk-f">${w}</span>`;
        else out+=w;
      } else {
        const U=w.toUpperCase();
        if(SQL_KW.has(U)) out+=`<span class="tk-k">${w}</span>`;
        else if(SQL_FN.has(U)) out+=`<span class="tk-b">${w}</span>`;
        else out+=w;
      }
    }
    else if(o) out+=`<span class="tk-o">${esc(o)}</span>`;
    else out+=esc(t);
  }
  return out;
}
const LANG = {python:["Python","#5B8CFF"],sql:["SQL","#22D3EE"],text:["Example","#A78BFA"]};
function codeBlock(src){
  const lang = detectLang(src), [label,col] = LANG[lang];
  return `<div class="codeblock"><div class="cb-head"><span class="cb-lang" style="--lc:${col}"><i></i>${label}</span><button class="copy" data-copy>${IC.copy}Copy</button></div><pre><code>${highlight(src,lang)}</code></pre></div>`;
}

/* ===================== content renderers ===================== */
function block(b){
  switch(b[0]){
    case "p": return `<p>${inline(b[1])}</p>`;
    case "ul": return `<ul>${b[1].map(x=>`<li>${inline(x)}</li>`).join("")}</ul>`;
    case "qs": return `<ol class="qs">${b[1].map(x=>`<li>${inline(x)}</li>`).join("")}</ol>`;
    case "code": return codeBlock(b[1]);
    case "f": return `<div class="formula${b[2]==="center"?" center":""}">${b[1].map(l=>`<div>${esc(l)}</div>`).join("")}</div>`;
    case "mat": return `<div class="mats">${b[1].map(([lab,rows])=>`<span class="mat-item"><span class="mat-lab">${esc(lab)}</span><table class="mat"><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join("")}</tr>`).join("")}</tbody></table></span>`).join("")}</div>`;
    case "solve": return solveList(b[1]);
    case "tip": return `<div class="tip"><span class="ti">${IC.bulb}</span><div><b>${esc(b[1])}</b>${inline(b[2])}</div></div>`;
    case "table": return `<div class="tbl"><table><thead><tr>${b[1].map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${b[2].map(r=>`<tr>${r.map(c=>`<td>${inline(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
  }
  return "";
}
/* ===================== point-by-point notes (pts.js) ===================== */
const PT_ABBR = /(?:\be\.g|\bi\.e|\betc|\bvs|\bapprox|\bMr|\bMrs|\bDr|\bSt|\bNo|\bFig)\.$/i;
/* split text into sentences ("sent") or on top-level semicolons ("semi"),
   never inside `code`, **bold**, "quotes" or (brackets) */
function ptSplit(t, mode){
  const out = []; let cur = "", bold = 0, tick = 0, q = 0, par = 0;
  for(let i = 0; i < t.length; i++){
    const c = t[i];
    if(c === "`"){ tick ^= 1; cur += c; continue; }
    if(!tick && c === "*" && t[i+1] === "*"){ bold ^= 1; cur += "**"; i++; continue; }
    if(!tick && c === '"') q ^= 1;
    if(!tick && c === "(") par++;
    if(!tick && c === ")" && par) par--;
    cur += c;
    if(tick || bold || q || par) continue;
    if(mode === "sent" && (c === "." || c === "!" || c === "?") && t[i+1] === " "){
      if(/^(?:\*\*|["'`(])?[A-Z0-9]/.test(t.slice(i+2, i+6)) && !PT_ABBR.test(cur)){ out.push(cur.trim()); cur = ""; i++; }
    } else if(mode === "semi" && c === ";" && t[i+1] === " "){
      out.push(cur.slice(0, -1).trim()); cur = ""; i++;
    }
  }
  if(cur.trim()) out.push(cur.trim());
  const m = [];
  out.forEach(s => { if(m.length && s.length < 18) m[m.length-1] += " " + s; else m.push(s); });
  return m;
}
const ptCap = s => s ? s[0].toUpperCase() + s.slice(1) : s;
/* "**Label:** rest" or "**Label**" alone -> [label, rest] */
function ptLabel(t){
  const m = t.match(/^\*\*([^*]+)\*\*\s*([\s\S]*)$/);
  if(!m) return null;
  let lab = m[1].trim(), rest = m[2].trim();
  if(rest.startsWith(":")){ rest = rest.slice(1).trim(); lab += ":"; }
  const ex = /\b(worked example|example|case study|scenario)\b/i.test(lab);
  if(!ex && rest && !/[:.?]$/.test(lab)) return null;
  if(!ex && lab.split(/\s+/).length > 12) return null;
  return [lab.replace(/[:.]$/, "").trim(), rest, ex];
}
const PT_DEF = /^(?:(?:A|An|The)\s+)?\*\*[^*]{1,60}\*\*\s*(?:\([^)]*\)\s*)?(?:is|are|was|were|means|refers to|stands for|describes|lets|allows)\b/;
const PT_NOTE = /^(note|remember|important|tip|hint|careful|warning|caution)$/i;
function ptKeywords(blocks){
  const seen = new Set(), out = [];
  blocks.forEach(b => {
    const txt = b[0] === "p" ? b[1] : b[0] === "ul" ? b[1].join(" ") : "";
    (txt.match(/\*\*([^*]{2,40})\*\*/g) || []).forEach(x => {
      const w = x.slice(2, -2).trim();
      if(/[:.]$/.test(w) || /example|^\d/i.test(w) || w.split(/\s+/).length > 4 || /^[a-z]/.test(w) && w.length < 4) return;
      const k = w.toLowerCase(); if(seen.has(k)) return; seen.add(k); out.push(w);
    });
  });
  return out.slice(0, 10);
}
function secBody(blocks, noKw){
  let h = "", pts = [], card = null;
  const emit = s => { if(card) card.body += s; else h += s; };
  const flushPts = () => { if(pts.length){ emit(`<ul class="pts">${pts.map(x => `<li>${inline(x)}</li>`).join("")}</ul>`); pts = []; } };
  const closeCard = () => { flushPts(); if(card){ h += `<div class="excard"><div class="ex-h"><span class="ex-i" aria-hidden="true">✏️</span><span>${inline(card.title)}</span></div><div class="ex-b">${card.body}</div></div>`; card = null; } };
  const paragraph = (text, next, cap) => {
    let ss = ptSplit(text, "sent");
    if(cap && ss.length && /^[a-z]/.test(ss[0]) && !/^[a-z_]+[(.\[=]/.test(ss[0])) ss[0] = ptCap(ss[0]);
    if(ss.length === 1 && (text.match(/; /g) || []).length >= 2){ const sm = ptSplit(text, "semi"); if(sm.length >= 3) ss = sm.map(ptCap); }
    ss.forEach((s, k) => {
      const last = k === ss.length - 1;
      if(k === 0 && PT_DEF.test(s)){ flushPts(); emit(`<div class="pt-def"><span class="pd-k">📌 Key term</span><p>${inline(s)}</p></div>`); }
      else if(last && /:$/.test(s) && next && /^(ul|qs|table|code|f|mat|solve)$/.test(next[0])){ flushPts(); emit(`<p class="pt-lead">${inline(s)}</p>`); }
      else pts.push(s);
    });
  };
  const kw = noKw ? [] : ptKeywords(blocks);
  if(kw.length >= 3) h += `<div class="kw"><span class="kw-l">Key words</span>${kw.map(w => `<button type="button" data-kw="${esc(w)}">${esc(w)}</button>`).join("")}</div>`;
  blocks.forEach((b, i) => {
    const next = blocks[i+1];
    if(b[0] === "p"){
      const L = ptLabel(b[1]);
      if(L && L[2]){ closeCard(); card = {title: L[0], body: ""}; if(L[1]) paragraph(L[1], next, true); return; }
      if(card && (L || PT_DEF.test(b[1]) || b[1].length > 220)) closeCard();
      if(L){
        flushPts();
        if(PT_NOTE.test(L[0]) && L[1]){ emit(`<div class="tip"><span class="ti">${IC.bulb}</span><div><b>${esc(L[0])}</b>${inline(L[1])}</div></div>`); return; }
        emit(`<h3 class="pt-sub">${inline(L[0])}</h3>`);
        if(L[1]) paragraph(L[1], next, true);
        return;
      }
      paragraph(b[1], next); return;
    }
    if(b[0] === "tip"){ closeCard(); h += block(b); return; }
    flushPts(); emit(block(b));
  });
  closeCard();
  return h;
}
document.addEventListener("click", e => {
  const k = e.target.closest("[data-kw]"); if(!k) return;
  const page = k.closest(".page") || document;
  const w = k.dataset.kw.toLowerCase();
  const hit = [...page.querySelectorAll("strong")].find(s => (k.compareDocumentPosition(s) & 4) && s.textContent.trim().toLowerCase() === w);
  if(!hit) return;
  hit.scrollIntoView({behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "center"});
  hit.classList.remove("kw-flash"); void hit.offsetWidth; hit.classList.add("kw-flash");
});
