      <div class="ch-top"><span class="ch-icon" aria-hidden="true">${c.subj.icon}</span>
        <div><h1>${esc(c.subject)}</h1><p class="meta">Class ${c.grade} · code ${c.code} · ${c.study.length} chapters · ${theoryTotal(c)} theory marks</p></div></div>
