  async function dgQuestRun(){
    const lv = QUEST_PY[dgQLevel];
    const out = document.querySelector("[data-dg-out]"), ta = document.querySelector("[data-dg-code]"),
      sprite = document.querySelector("[data-dgq-sprite]"), blocksEl = document.querySelector("[data-dgq-blocks]");
    if(!lv || !out || !ta || !sprite) return;
    const code = ta.value;
    out.textContent = "Running…"; out.className = "dg-out";
    if(blocksEl) blocksEl.innerHTML = "";
    const actions = [];
    let px = lv.start.x, py = lv.start.y;
    try{
      const pyo = await getPyodide();
      pyo.globals.set("move_right", () => { px = Math.min(lv.cols - 1, px + 1); actions.push({type:"move", x:px, y:py}); });
      pyo.globals.set("move_left", () => { px = Math.max(0, px - 1); actions.push({type:"move", x:px, y:py}); });
      pyo.globals.set("move_down", () => { py = Math.min(lv.rows - 1, py + 1); actions.push({type:"move", x:px, y:py}); });
      pyo.globals.set("move_up", () => { py = Math.max(0, py - 1); actions.push({type:"move", x:px, y:py}); });
      pyo.globals.set("jump", () => { actions.push({type:"jump", x:px, y:py}); });
      pyo.globals.set("place_block", () => { actions.push({type:"block", x:px, y:py}); });
      pyo.runPython("sys.stdout = io.StringIO()");
      pyo.runPython(code);
      if(!actions.length){ out.textContent = "Your code didn't move the robot. Try move_right(), move_left(), move_up(), move_down(), place_block() or jump()."; out.classList.add("bad"); return; }
      out.textContent = "Watch the robot go…";
      let blockCount = 0, jumped = false;
      const cellPct = (v, n) => ((v + 0.5) / n * 100).toFixed(2);
      for(const a of actions){
        await new Promise(r => setTimeout(r, 380));
        if(a.type === "move"){ sprite.style.left = cellPct(a.x, lv.cols) + "%"; sprite.style.top = cellPct(a.y, lv.rows) + "%"; }
        else if(a.type === "jump"){ sprite.classList.remove("hop"); void sprite.offsetWidth; sprite.classList.add("hop"); jumped = true; }
        else if(a.type === "block"){
          blockCount++;
          if(blocksEl){
            const b = document.createElement("span");
            b.className = "dgq-block"; b.textContent = "🧱";
            b.style.left = cellPct(a.x, lv.cols) + "%"; b.style.top = cellPct(a.y, lv.rows) + "%"; b.style.marginTop = (-14 * blockCount) + "px";
            blocksEl.appendChild(b);
          }
        }
      }
      await new Promise(r => setTimeout(r, 200));
      const won = lv.build ? (blockCount >= lv.blocksNeeded && jumped) : (px === lv.goal.x && py === lv.goal.y);
      if(won){
        out.textContent = "🏆 Level complete! +" + lv.xp + " points.";
        out.classList.add("ok");
        dgAward("quest:" + lv.id, lv.xp);
        if(typeof rerender === "function") rerender();
        dgRefreshCard();
      } else {
        out.textContent = lv.build ? ("Not quite — place at least " + lv.blocksNeeded + " blocks, then jump() on top.") : "Not quite — the robot didn't reach the flag. Try again!";
        out.classList.add("bad");
      }
    }catch(err){
      out.textContent = "❌ " + (err && err.message || String(err));
      out.classList.add("bad");
    }
  }
  async function dgMineRun(){
    const lv = MINE_SQL[dgMLevel];
    const out = document.querySelector("[data-dg-out]"), ta = document.querySelector("[data-dg-code]"), grid = document.querySelector("[data-dgm-grid]");
    if(!lv || !out || !ta) return;
    const code = ta.value;
    out.textContent = "Mining…"; out.className = "dg-out";
    if(grid) grid.querySelectorAll("[data-dgm-tile]").forEach(t => { t.textContent = "🪨"; t.classList.remove("dug"); });
    try{
      const SQLlib = await getSqlJs();
      const db = new SQLlib.Database();
      db.run(SQL_SETUP);
      let rows = [];
      try{ const res = db.exec(code); rows = (res[0] && res[0].values) || []; }
      catch(sqlErr){ out.textContent = "❌ SQL error: " + sqlErr.message; out.classList.add("bad"); db.close(); return; }
      db.close();
      const gotNames = rows.map(r => String(r[0]).trim());
      const matched = [];
      for(const [idStr, nm] of Object.entries(MINE_NAMES)){
        if(gotNames.includes(nm)){
          matched.push(idStr);
          await new Promise(r => setTimeout(r, 300));
          const tile = grid ? grid.querySelector(`[data-dgm-tile="${idStr}"]`) : null;
          if(tile){ tile.textContent = "💎"; tile.classList.add("dug"); }
        }
      }
      const a = matched.slice().sort();
      const b = Object.entries(MINE_NAMES).filter(([, nm]) => lv.expect.includes(nm)).map(([id]) => id).sort();
      const won = a.length === b.length && a.every((v, idx) => v === b[idx]);
      if(won){
        out.textContent = "🏆 Mined it! +" + lv.xp + " points.";
        out.classList.add("ok");
        dgAward("mine:" + lv.id, lv.xp);
        if(typeof rerender === "function") rerender();
        dgRefreshCard();
      } else {
        out.textContent = "Not quite the right tiles — try again!";
        out.classList.add("bad");
      }
    }catch(err){
      out.textContent = "❌ " + (err && err.message || String(err));
      out.classList.add("bad");
    }
  }
